files.main.tf:
terraform {
 required_providers {
  aws = { source = "hashicorp/aws", version = "5.100.0" }
 }
}
variable "primary" { type = string }
variable "backup" { type = string }
resource "aws_batch_job_queue" "shared" {
 name = "shared-batch"
 state = "ENABLED"
 priority = 3
 compute_environments = [var.primary, var.backup]
}
output "queue_arn" { value = aws_batch_job_queue.shared.arn }

terraform {
 required_providers {
  aws = { source = "hashicorp/aws", version = "5.100.0" }
 }
}
provider "aws" { region = "us-east-1" }
module "queue" {
 source = "git::https://github.com/aetna000/atmem-maintenance-r3-module.git?ref=v1.0.0"
 primary = "arn:aws:batch:us-east-1:123456789012:compute-environment/primary"
 backup = "arn:aws:batch:us-east-1:123456789012:compute-environment/backup"
}
output "queue" { value = module.queue.queue_arn }

terraform {
 required_providers {
  aws = { source = "hashicorp/aws", version = "5.100.0" }
 }
}
provider "aws" { region = "eu-west-1" }
module "archive" {
 source = "git::https://github.com/aetna000/atmem-maintenance-r3-module.git?ref=v1.0.0"
 primary = "arn:aws:batch:eu-west-1:123456789012:compute-environment/primary"
 backup = "arn:aws:batch:eu-west-1:123456789012:compute-environment/backup"
}

terraform {
 required_providers {
  aws = { source = "hashicorp/aws", version = "6.0.0" }
 }
}
resource "aws_s3_bucket" "unrelated" { bucket = "maintenance-unrelated" }
